function seedingFor({ databaseIsFresh, willSeed }) {
  if (willSeed) {
    if (databaseIsFresh) {
      return 'seed';
    } else {
      return 'reseed';
    }
  } else {
    if (databaseIsFresh) {
      return 'leave-unseeded';
    } else {
      return 'leave-unchanged';
    }
  }
}

/**
 * A failed re-seed only leaves the sample data as far as the seeder got, on a database that worked
 * a moment ago, so it warns instead of failing the run — which would also stop the dev servers. A
 * first seed stays fatal: an unseeded instance is no use. The seeded marker stays as it was.
 */
export async function reseedOrWarn(runSeeder, warn = console.warn) {
  try {
    await runSeeder();
  } catch (error) {
    if (error instanceof StepFailedError) {
      warn(
        `\n${error.message}\n\nWARNING: re-seeding failed, so the instance comes up with its sample ` +
          'data as far as the seeder got. `just up --seed` tries again.',
      );
    } else {
      throw error;
    }
  }
}

// `--profile limesurvey` has to sit before the subcommand, exactly like the `--profile seed` call
// below it already does — both are `docker compose` global flags, not arguments to `up` itself.
export function seedArgs() {
  return [
    '--profile',
    'seed',
    'up',
    '--force-recreate',
    '--exit-code-from',
    'sample-data-loader',
    'sample-data-loader',
  ];
}

export function composeCreateArgs(options) {
  // `create` builds the image and creates the network and containers WITHOUT starting them. The
  // network has to exist before the proxy can be attached to it, and nothing may start before that
  // attachment: the backend reaches Keycloak under the instance's public name, which only resolves
  // inside the network once the proxy answers to it there. Starting first deadlocks — the backend
  // crash-loops waiting for a proxy that `--wait` is blocking the attachment of.
  const args = ['create', '--build'];
  if (options.limesurvey) {
    return ['--profile', 'limesurvey', ...args];
  } else {
    return args;
  }
}

export function composeUpArgs(options) {
  const upArgs = ['up', '-d', '--wait'];
  if (options.limesurvey) {
    return ['--profile', 'limesurvey', ...upArgs];
  } else {
    return upArgs;
  }
}

/**
 * A fresh run starts with neither the app's sample data nor Keycloak's realm actually imported —
 * `--fresh` wipes the volume both live in (see `startAndWait`'s and the realm-drift check's own
 * comments), so any marker recorded before the wipe describes a database that no longer exists.
 * Pulled out on its own so "does `--fresh` clear both markers" is a plain, disk-backed unit test
 * instead of only reachable through `main()`'s full docker-and-network sequence.
 */
export function clearFreshState({ seededMarker, realmHashMarker }) {
  rmSync(seededMarker, { force: true });
  rmSync(realmHashMarker, { force: true });
}

/**
 * Of the instances `ensureProxy` had to reattach after force-recreating the shared proxy for a
 * port change, the ones whose *own* rendered artifacts still say the old port — their containers
 * keep working (the Keycloak issuer only depends on the public hostname, not the port), but their
 * browsers now point at a proxy that no longer listens where they expect, and nothing about a
 * successful-looking `just up` would otherwise say so.
 */
export function staleReattachedInstances(reattached, proxyPort, readProxyPortFor = readProxyPort) {
  return reattached.filter((instance) => {
    try {
      return readProxyPortFor(instance) !== proxyPort;
    } catch {
      // No readable rendered port for that instance — nothing to compare, so don't warn about it.
      return false;
    }
  });
}

